// Помощники для нижней навигации (#8b5196, #4777a0): вкладки, активное состояние, положение «ореола» (nav-glow).
// Ореол — блок с картинкой nav-glow.png; его центр по X сравниваем с центром вкладки.
// Активная вкладка: подпись font-rubik + text-white (неактивная — font-rubik-light), залитая белая иконка (opacity 1).
import { expect, type Page } from '@playwright/test';

export const TABS = {
  'הודעות': '/matches',
  'לייקים': '/likes',
  'גילוי': '/discover',
  'מיקום': '/map',
  'חדרים': '/social',
} as const;
export type TabName = keyof typeof TABS;

export const tab = (page: Page, name: TabName) => page.getByRole('tab', { name, exact: true });

export type GlowState = { cx: number; op: number } | null;

/** Центр ореола по X и его прозрачность (null — ореола нет в DOM). */
export async function glow(page: Page): Promise<GlowState> {
  return page.evaluate(() => {
    const imgs = [...document.querySelectorAll('img[src*="nav-glow"]')] as HTMLElement[];
    const box = imgs.map((i) => i.parentElement?.parentElement).filter((e): e is HTMLElement => !!e && e.getBoundingClientRect().width > 0).pop();
    if (!box) return null;
    const r = box.getBoundingClientRect();
    return { cx: r.left + r.width / 2, op: Number(getComputedStyle(box).opacity) };
  });
}

/** Центр вкладки по X. */
export async function tabCenter(page: Page, name: TabName): Promise<number> {
  const b = await tab(page, name).boundingBox();
  if (!b) throw new Error(`вкладка ${name} не видна`);
  return b.x + b.width / 2;
}

/** Состояние «активна» вкладки: подпись белая не-light и залитая иконка видима. */
export async function isActive(page: Page, name: TabName): Promise<boolean> {
  return tab(page, name).evaluate((t) => {
    const label = t.querySelector('div[dir="rtl"]');
    const labelOn = !!label && /\bfont-rubik\b/.test(label.className) && !/font-rubik-light/.test(label.className) && /\btext-white\b/.test(label.className);
    // Две иконки-слоя: [0] контурная, [1] залитая (absolute). Активная — залитая с opacity 1.
    const layers = t.firstElementChild ? ([...t.firstElementChild.children] as HTMLElement[]) : [];
    const filled = layers[1] ? Number(getComputedStyle(layers[1]).opacity) : 0;
    return labelOn && filled > 0.9;
  });
}

/** Ждём, пока ореол встанет над вкладкой (±4 px) и будет видим. */
export async function expectGlowOn(page: Page, name: TabName) {
  const target = await tabCenter(page, name);
  await expect
    .poll(async () => {
      const g = await glow(page);
      return !!g && g.op > 0.9 && Math.abs(g.cx - target) <= 4;
    }, { message: `ореол над «${name}»`, timeout: 5_000 })
    .toBe(true);
}

/** Запускает запись положения ореола на каждом кадре (requestAnimationFrame) в window.__qaGlow на ms миллисекунд. */
export async function startGlowRecorder(page: Page, ms = 1500) {
  await page.evaluate((dur) => {
    const w = window as unknown as { __qaGlow: { t: number; cx: number; op: number }[]; __qaGlowDone: boolean };
    w.__qaGlow = [];
    w.__qaGlowDone = false;
    const t0 = performance.now();
    const frame = (now: number) => {
      const imgs = [...document.querySelectorAll('img[src*="nav-glow"]')] as HTMLElement[];
      const box = imgs.map((i) => i.parentElement?.parentElement).filter((e): e is HTMLElement => !!e && e.getBoundingClientRect().width > 0).pop();
      if (box) {
        const r = box.getBoundingClientRect();
        w.__qaGlow.push({ t: now - t0, cx: r.left + r.width / 2, op: Number(getComputedStyle(box).opacity) });
      }
      if (now - t0 < dur) requestAnimationFrame(frame);
      else w.__qaGlowDone = true;
    };
    requestAnimationFrame(frame);
  }, ms);
}

export async function readGlowRecord(page: Page) {
  await expect.poll(() => page.evaluate(() => (window as unknown as { __qaGlowDone: boolean }).__qaGlowDone), { timeout: 10_000 }).toBe(true);
  return page.evaluate(() => (window as unknown as { __qaGlow: { t: number; cx: number; op: number }[] }).__qaGlow);
}

/**
 * Разбор записи перехода ореола от from к to:
 * moving — кадры строго между точками (дальше 3 px от обеих), durationMs — от первого сдвига до прихода (±3 px),
 * backSteps — шаги назад (> 2 px против направления), maxStep — самый большой скачок за кадр.
 */
export function analyseSlide(rec: { t: number; cx: number }[], from: number, to: number) {
  const dir = Math.sign(to - from);
  const moving = rec.filter((s) => Math.abs(s.cx - from) > 3 && Math.abs(s.cx - to) > 3 && (s.cx - from) * dir > 0 && (to - s.cx) * dir > 0);
  const firstMove = rec.find((s) => Math.abs(s.cx - from) > 3);
  const arrive = rec.find((s) => Math.abs(s.cx - to) <= 3);
  let backSteps = 0;
  let maxStep = 0;
  for (let i = 1; i < rec.length; i++) {
    const d = rec[i].cx - rec[i - 1].cx;
    if (d * dir < -2) backSteps++;
    maxStep = Math.max(maxStep, Math.abs(d));
  }
  return {
    moving: moving.length,
    durationMs: firstMove && arrive ? arrive.t - firstMove.t : NaN,
    backSteps,
    maxStep,
    distance: Math.abs(to - from),
  };
}
